CREATE TABLE IF NOT EXISTS finfolk.site_catalog (id integer NOT NULL, revision bigint NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY (id), CHECK ((id = 1)), CHECK ((revision >= 0)));
CREATE TABLE IF NOT EXISTS finfolk.site_profiles (id text NOT NULL, revision bigint NOT NULL, waterbody text NOT NULL, access_mode text NOT NULL, status text NOT NULL, payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id), FOREIGN KEY (id) REFERENCES finfolk.beaches(id), CHECK ((waterbody = ANY (ARRAY['ocean'::text, 'lake'::text, 'river'::text, 'quarry'::text, 'sinkhole'::text, 'pool'::text, 'unknown'::text]))), CHECK ((access_mode = ANY (ARRAY['shore'::text, 'boat_only'::text, 'shore_or_boat'::text, 'unknown'::text]))), CHECK ((status = ANY (ARRAY['published'::text, 'archived'::text]))));
CREATE TABLE IF NOT EXISTS finfolk.site_imports (id uuid NOT NULL DEFAULT gen_random_uuid(), owner_id text, preview jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft'::text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id), FOREIGN KEY (owner_id) REFERENCES finfolk.members(user_id) ON DELETE SET NULL, CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text]))));
CREATE TABLE IF NOT EXISTS finfolk.site_revisions (id uuid NOT NULL DEFAULT gen_random_uuid(), site_id text NOT NULL, owner_id text, import_id uuid, base_revision bigint NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 1, status text NOT NULL, payload jsonb NOT NULL, reason text NOT NULL DEFAULT ''::text, reviewed_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id), FOREIGN KEY (owner_id) REFERENCES finfolk.members(user_id) ON DELETE SET NULL, FOREIGN KEY (reviewed_by) REFERENCES finfolk.members(user_id) ON DELETE SET NULL, FOREIGN KEY (import_id) REFERENCES finfolk.site_imports(id) ON DELETE CASCADE, CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'published'::text, 'rejected'::text, 'withdrawn'::text]))));
CREATE TABLE IF NOT EXISTS finfolk.site_access_points (id uuid NOT NULL DEFAULT gen_random_uuid(), revision_id uuid NOT NULL, mode text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY (id), FOREIGN KEY (revision_id) REFERENCES finfolk.site_revisions(id) ON DELETE CASCADE, CHECK ((mode = ANY (ARRAY['shore'::text, 'departure'::text]))));
CREATE TABLE IF NOT EXISTS finfolk.site_depth_evidence (id uuid NOT NULL DEFAULT gen_random_uuid(), revision_id uuid NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY (id), FOREIGN KEY (revision_id) REFERENCES finfolk.site_revisions(id) ON DELETE CASCADE, CHECK ((kind = ANY (ARRAY['surveyed'::text, 'reported'::text]))));
CREATE INDEX IF NOT EXISTS site_revisions_owner_idx ON finfolk.site_revisions(owner_id,updated_at);
CREATE INDEX IF NOT EXISTS site_revisions_import_idx ON finfolk.site_revisions(import_id);
CREATE INDEX IF NOT EXISTS site_revisions_status_idx ON finfolk.site_revisions(status,updated_at);
INSERT INTO finfolk.site_catalog(id) VALUES(1) ON CONFLICT DO NOTHING;
GRANT SELECT,INSERT,UPDATE,DELETE ON finfolk.site_catalog,finfolk.site_profiles,finfolk.site_imports,finfolk.site_revisions,finfolk.site_access_points,finfolk.site_depth_evidence TO finfolk_api;
